package com.club.service;
import com.club.dto.*; import com.club.repository.SocioRepository; import org.junit.jupiter.api.Test; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class SocioServiceTest { @Test void registraNormalizando(){var r=mock(SocioRepository.class);when(r.existsByEmailIgnoreCaseAndEliminadoFalse("a@mail.com")).thenReturn(false);when(r.save(any())).thenAnswer(i->i.getArgument(0));SocioResponse s=new SocioService(r).registrar(new RegistrarSocioDTO(" Ana "," Perez "," A@MAIL.COM "," 261 ",LocalDate.of(2000,1,1)));assertEquals("Ana",s.nombre());assertEquals("a@mail.com",s.email());} @Test void fechaFutura(){var r=mock(SocioRepository.class);assertThrows(RuntimeException.class,()->new SocioService(r).registrar(new RegistrarSocioDTO("Ana","Perez","a@a.com","261",LocalDate.now().plusDays(1))));}}
